{"findings":[{"tipo":"GC","causa_raiz":"Alocação excessiva na heap gerenciada (6.706.563 bytes em um único frame), disparando uma coleta de lixo síncrona com pausa de 23.18ms. Isso excede a margem de segurança do frame budget (27.0ms) quando somado ao tempo de CPU (21.61ms), gerando stuttering visível.","codigo_refatorado":"using System.Collections.Generic;
using UnityEngine;

public class ProjectileManager : MonoBehaviour
{
    [SerializeField] private GameObject projectilePrefab;
    [SerializeField] private int initialPoolSize = 100;

    private readonly Queue<GameObject> _pool = new Queue<GameObject>();
    private readonly List<GameObject> _activeObjects = new List<GameObject>(128);
    private static readonly Collider[] HitBuffer = new Collider[32];

    private void Awake()
    {
        for (int i = 0; i < initialPoolSize; i++)
        {
            GameObject obj = Instantiate(projectilePrefab, transform);
            obj.SetActive(false);
            _pool.Enqueue(obj);
        }
    }

    public GameObject Spawn(Vector3 position, Quaternion rotation)
    {
        GameObject instance = _pool.Count > 0 ? _pool.Dequeue() : Instantiate(projectilePrefab, transform);
        instance.transform.SetPositionAndRotation(position, rotation);
        instance.SetActive(true);
        _activeObjects.Add(instance);
        return instance;
    }

    public void Despawn(GameObject instance)
    {
        instance.SetActive(false);
        _activeObjects.Remove(instance);
        _pool.Enqueue(instance);
    }

    public int CheckAreaOverlap(Vector3 center, float radius, LayerMask mask)
    {
        return Physics.OverlapSphereNonAlloc(center, radius, HitBuffer, mask);
    }
}","explicacao_didatica":"Quando o jogo cria muitos objetos ou listas temporárias de uma vez, a Unity usa a memória do 'Garbage Collector' (GC). Quando essa memória enche, o jogo precisa congelar por alguns milissegundos para limpar a sujeira (Garbage Collection). No seu snapshot, o jogo parou por 23.18ms para limpar 6.7MB de dados, causando uma travadinha visível. A solução é reutilizar os objetos usando um padrão chamado Object Pool e usar métodos 'NonAlloc' da Unity, evitando criar e destruir coisas durante a partida."}],"dicas_level_design":null}

